{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Ensure that 'enable_https_traffic_only' is enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The storage account allows HTTP traffic, which exposes data in transit to interception and man-in-the-middle attacks. HTTPS should be enforced."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Ensure Storage Account is using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The minimum TLS version is set to TLS1_0, which is deprecated and vulnerable to known security flaws. It should be updated to at least TLS1_2."
    },
    {
      "check_id": "CKV_AZURE_59",
      "title": "Ensure that Storage accounts disallow public access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Public blob access is not explicitly disabled. By default, Azure may allow anonymous access depending on configuration; it is best practice to explicitly deny public network access or disable public blob access."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Ensure soft-delete is enabled on Azure storage account",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Blob soft delete is not configured. Enabling soft delete protects against accidental deletion or overwriting of blobs by retaining them for a specified period."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version          = \"TLS1_2\"\n  public_network_access_enabled = false\n  blob_properties {\n    versioning_enabled = true\n    container_delete_retention_policy {\n      days = 7\n    }\n    delete_retention_policy {\n      days = 7\n    }\n  }\n}",
  "fix_summary": "Enabled HTTPS-only traffic, upgraded minimum TLS version to 1.2, disabled public network access, and added blob/container delete retention policies (soft delete) to enhance security and data protection."
}
